#include "fedspatial/gpu_context.hpp"
#include "fedspatial/nworker_15k_figure1_config.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdlib>
#include <iostream>
using namespace fedspatial;
namespace {
int test_dim(const char* name,int fallback){const char* e=std::getenv(name);return e&&e[0]?std::atoi(e):fallback;}
WorkerInput worker(){const int n=test_dim("FEDSPATIAL_TEST_N",128);Matrix s(n,2),z(n,1),x(n,1);for(int i=0;i<n;++i){s(i,0)=.013*i;s(i,1)=.021*(i%11);z(i,0)=std::sin(.071*(i+1)*5)+.03*i;x(i,0)=1.;}return{s,z,x};}
Matrix knots(){const int m=test_dim("FEDSPATIAL_TEST_M",64);Matrix k(m,2);for(int j=0;j<m;++j){k(j,0)=.019*j+.004;k(j,1)=.017*(j%13)+.002;}return k;}
GlobalParameters parameters(){const int m=test_dim("FEDSPATIAL_TEST_M",64);Matrix g(1,1),mu(m,1),sigma(m,m);g(0,0)=.1;for(int i=0;i<m;++i){mu(i,0)=.01*std::cos(.1*i);for(int j=0;j<m;++j)sigma(i,j)=(i==j?.9:0.)+.002*std::exp(-.03*std::abs(i-j));}return{g,mu,sigma,.7,1.15,.43};}
void base_gates(){for(const char* n:{"FEDSPATIAL_MIXED_TRACE_TILED_ACTION","FEDSPATIAL_MIXED_CONTRACTIONS_TILED","FEDSPATIAL_THETA_FIRST_TILED","FEDSPATIAL_THETA_HESSIAN_AA_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_AR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_RR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_Q_W_TILED"})setenv(n,"1",1);}
double maxdiff(const DeltaThetaLocalResult&a,const DeltaThetaLocalResult&b){double x=std::abs(a.objective-b.objective);for(int i=0;i<3;++i)x=std::max(x,std::abs(a.gradient[i]-b.gradient[i]));for(int i=0;i<9;++i)x=std::max(x,std::abs(a.hessian[i]-b.hessian[i]));return x;}
double maxrel(const DeltaThetaLocalResult&a,const DeltaThetaLocalResult&b){auto r=[](double x,double y){return std::abs(x-y)/std::max({1.,std::abs(x),std::abs(y)});};double x=r(a.objective,b.objective);for(int i=0;i<3;++i)x=std::max(x,r(a.gradient[i],b.gradient[i]));for(int i=0;i<9;++i)x=std::max(x,r(a.hessian[i],b.hessian[i]));return x;}
}
int main(){try{setenv("CUDA_VISIBLE_DEVICES",NWorker15kFigure1Config::gv100_uuid_0,1);base_gates();const auto w=worker();const auto k=knots();const auto p=parameters();GpuContext c(0);const bool tiled_only=[](){const char*e=std::getenv("FEDSPATIAL_BENCH_ONLY_TILED");return e&&e[0]&&e[0]!='0';}();const bool scalar_only=[](){const char*e=std::getenv("FEDSPATIAL_BENCH_ONLY_SCALAR");return e&&e[0]&&e[0]!='0';}();auto report=[&](const char* tag,const DeltaThetaLocalResult&v,double ms){std::cout<<tag<<" n="<<w.sites.rows<<" m="<<k.rows<<" ms="<<ms<<" values="<<v.objective;for(double x:v.gradient)std::cout<<","<<x;for(double x:v.hessian)std::cout<<","<<x;std::cout<<std::endl;};if(tiled_only||scalar_only){setenv("FEDSPATIAL_THETA_HESSIAN_SECOND_LOG_TILED",tiled_only?"1":"0",1);const auto t0=std::chrono::steady_clock::now();const auto only=compute_device_delta_theta_local(c,w,k,p).summary;const auto t1=std::chrono::steady_clock::now();report(tiled_only?"THETA_SECOND_LOG_TILED_ONLY":"THETA_SECOND_LOG_SCALAR_ONLY",only,std::chrono::duration<double,std::milli>(t1-t0).count());return 0;}const auto a0=std::chrono::steady_clock::now();const auto before=compute_device_delta_theta_local(c,w,k,p).summary;const auto a1=std::chrono::steady_clock::now();setenv("FEDSPATIAL_THETA_HESSIAN_SECOND_LOG_TILED","1",1);const auto after=compute_device_delta_theta_local(c,w,k,p).summary;const auto a2=std::chrono::steady_clock::now();const double b=std::chrono::duration<double,std::milli>(a1-a0).count(),a=std::chrono::duration<double,std::milli>(a2-a1).count(),d=maxdiff(before,after),r=maxrel(before,after);std::cout<<"THETA_SECOND_LOG_TILED_BENCH n="<<w.sites.rows<<" m="<<k.rows<<" before_ms="<<b<<" after_ms="<<a<<" speedup="<<b/a<<" max_abs="<<d<<" max_rel="<<r<<std::endl;return r<=1e-9?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
